mapper.select:
SELECT sa.AREA_CODE from sys_area sa LEFT JOIN sys_area_manage_rel samr ON samr.area_code=sa.AREA_CODE WHERE samr.dept_code IN ( SELECT area.dept_id FROM sys_dept area WHERE area.del_flag = 0 and area.tenant_id is null and
area.dept_level > 2 AND area.dept_id = ( SELECT LEFT ( vuser.dept_id, 6 ) FROM sys_user vuser WHERE vuser.user_id = #{userId} ) OR ( area.dept_level = 2 and area.tenant_id is null and area.dept_id like CONCAT((SELECT LEFT ( vuser.dept_id, 4 ) FROM sys_user vuser WHERE vuser.user_id = #{userId}),'%') ) ) and (sa.area_level = #{areaLevel}
or (sa.area_level = 4 and sa.area_code REGEXP '^110|^500|^120|^310')
)

SELECT c.tenant_id FROM vm_order_customer c WHERE c.business_org
#{item.deptId}
UNION
SELECT c.tenant_id FROM vm_order_customer_his c WHERE c.business_org
#{item.deptId}

select distinct device_code from vm_organ_device_rel_t
WHERE delete_flag = '0' and industry_code = #{industryCode}


        and dept_id in

            #{item}



        and dept_id in ('')



    and FIND_IN_SET(device_type,#{alarmSource})

select dept_id
from sys_dept
where tenant_id = #{tenantId}

    and parent_id = #{orgId}

SELECT DISTINCT
    od.device_code
FROM
    vm_order_uav_nest_devices od
WHERE
    od.delete_flag = '0'
  AND od.ord_status IN ( 0, 1, 2 )
  AND od.tenant_id = #{tenantId}
  AND od.industry_code = #{industryCode}
  AND od.app_ver_code = #{appVerCode}

select count(*) from
vm_order_devices where
tenant_id = #{tenantId}
and ord_status in (0, 1, 2)
and industry_code = #{industryCode}
and delete_flag = 0

select count(*)
from vm_order_uav_devices where
tenant_id = #{tenantId}
and ord_status in (0, 1, 2)
and industry_code = #{industryCode}
and delete_flag = 0

select  count(*)
from vm_order_sensor_devices
where tenant_id = #{tenantId}
and ord_status in (0, 1, 2)
and industry_code = #{industryCode}
and category_code = #{categoryCode}
and delete_flag = 0

SELECT DISTINCT sat.type_value AS code, sat.alarm_source as source FROM sys_alarm_type sat left join sys_dict_data data on sat.alarm_source = data.DICT_VALUE and data.DICT_TYPE = 'warning_source_common' WHERE sat.delete_flag = 0 and sat.alarm_source in
#{alarmSource}
and ((sat.tenant_id is null and industry_code is null) or (sat.tenant_id = #{tenantId} and industry_code = #{industryCode}))

SELECT '11' AS source, t.alarm_type AS code FROM vm_third_party_alarm t WHERE t.delete_flag = 0
AND t.tenant_id = #{tenantId}
AND t.industry_code = #{industryCode}

select distinct layer_id from vm_organ_layer_rel_t
WHERE delete_flag = '0' and industry_code = #{industryCode}


        and dept_id in

            #{item}



        and dept_id in ('')
